#!/usr/bin/bash
# Lucent visual design: the packages and caches behind the look shipped in
# system_files/ (Plasma theme, window decoration, icons, launcher, wallpaper).
# Called from build.sh; sources and licenses are listed in THIRD_PARTY.md.
# The theme assets themselves are generated by design/*.py from
# docs/mockups/ and committed, so nothing here renders artwork.
set -xeuo pipefail

DNF=$(command -v dnf5 || command -v dnf)
DNF_OPTS=(-y --setopt=install_weak_deps=False)
FEDORA=$(rpm -E %fedora)

# Papirus (Fedora packages, GPL-3.0): every icon the Lucent icon theme
# doesn't draw itself (/usr/share/icons/Lucent inherits Papirus-Light,
# Lucent-Dark inherits Papirus-Dark; Fedora ships those two variants as
# separate packages, without them the chain falls through to Breeze and dark
# toolbars get dark glyphs).
"$DNF" "${DNF_OPTS[@]}" install papirus-icon-theme papirus-icon-theme-light papirus-icon-theme-dark

# Rounded window corners + hairline outline: KDE-Rounded-Corners (GPL-3.0)
# from its author's COPR. Its builds are tied to one KWin release (the RPM
# release is the KWin version). If no build for this image's KWin exists yet,
# the image still builds; windows then just keep square bottom corners.
curl -fsSL "https://copr.fedorainfracloud.org/coprs/matinlotfali/KDE-Rounded-Corners/repo/fedora-$FEDORA/matinlotfali-KDE-Rounded-Corners-fedora-$FEDORA.repo" \
    -o /etc/yum.repos.d/lucent-roundcorners.repo
kwin_version=$(rpm -q --qf '%{VERSION}' kwin)
if "$DNF" "${DNF_OPTS[@]}" install kwin-effect-roundcorners; then
    built_for=$(rpm -q --qf '%{RELEASE}' kwin-effect-roundcorners)
    if [[ "$built_for" != "$kwin_version".* ]]; then
        echo "WARNING: kwin-effect-roundcorners was built for KWin ${built_for%%.fc*}, image has $kwin_version; leaving it out"
        "$DNF" -y --setopt=clean_requirements_on_remove=False remove kwin-effect-roundcorners
    fi
else
    echo "WARNING: kwin-effect-roundcorners unavailable for Fedora $FEDORA; windows keep square bottom corners"
fi
rm -f /etc/yum.repos.d/lucent-roundcorners.repo

# A Windows switcher's launcher shows apps, not admin and developer tools:
# these stay installed but get NoDisplay (also hides them from search). Info
# Center and Firewall stay reachable from System Settings, Help from F1.
for id in firewall-config org.kde.kcharselect org.kde.kdebugsettings org.kde.kdeconnect.sms \
          org.kde.khelpcenter org.kde.kinfocenter org.kde.kmenuedit org.kde.kwalletmanager \
          org.kde.plasma.emojier org.kde.kfind org.kde.partitionmanager; do
    f=/usr/share/applications/$id.desktop
    [ -f "$f" ] || continue
    grep -q '^NoDisplay=true' "$f" || sed -i '0,/^\[Desktop Entry\]/s//[Desktop Entry]\nNoDisplay=true/' "$f"
done

# Icon caches for the generated Lucent themes (Papirus ships its own).
for theme in Lucent Lucent-Dark; do
    gtk-update-icon-cache -f "/usr/share/icons/$theme"
done

# Lucent Plasma packages (plain QML, no build step): fail early if incomplete.
for pkg in /usr/share/plasma/plasmoids/org.lucent.*; do
    test -f "$pkg/metadata.json" && test -f "$pkg/contents/ui/main.qml"
done

# Boot splash: Lucent logo + Fedora's spinner frames (plymouth-theme-spinner,
# GPL-2.0-or-later) copied into the lucent theme, then the initramfs is
# rebuilt so Plymouth has the theme before the root filesystem is mounted.
theme=/usr/share/plymouth/themes/lucent
for f in /usr/share/plymouth/themes/spinner/*.png; do
    [ "${f##*/}" = watermark.png ] || cp -a "$f" "$theme/"
done
plymouth-set-default-theme lucent
kver=$(ls /usr/lib/modules | head -n1)
DRACUT_NO_XATTR=1 dracut --no-hostonly --kver "$kver" --reproducible --zstd -v --add ostree \
    -f "/usr/lib/modules/$kver/initramfs.img"
lsinitrd "/usr/lib/modules/$kver/initramfs.img" > /tmp/initramfs.list
grep "plymouth/themes/lucent/lucent.plymouth" /tmp/initramfs.list
rm /tmp/initramfs.list

# Translations of the Lucent plasmoids (design/po/<domain>.<lang>.po), compiled
# with the wizard's own .mo writer, so the build needs no gettext tools.
for po in /ctx/design/po/*.po; do
    base=${po##*/}
    domain=${base%.*.po}
    lang=${base%.po}
    lang=${lang##*.}
    PYTHONPATH=/usr/lib/lucent python3 -P -c \
        'import sys; from pathlib import Path; from lucent_migrate.i18n import compile_po; compile_po(Path(sys.argv[1]), Path(sys.argv[2]))' \
        "$po" "/usr/share/locale/$lang/LC_MESSAGES/$domain.mo"
done
